using Eto.Drawing; using Eto.Forms; using Rhino; using Rhino.UI;
namespace RhinoContextAssist;
internal sealed class ContextToolbarForm:Form
{
    readonly Label _caption=new(); readonly StackLayout _primary=new(){Orientation=Orientation.Horizontal,Spacing=4}; readonly StackLayout _more=new(){Orientation=Orientation.Horizontal,Spacing=4,Visible=false};
    readonly Action<ContextAction> _execute; readonly Action _dismiss;
    public ContextToolbarForm(Action<ContextAction> execute,Action dismiss){_execute=execute;_dismiss=dismiss;Title="Context Assist";ShowInTaskbar=false;ShowActivated=false;Topmost=true;Resizable=false;WindowStyle=WindowStyle.None;Padding=7;this.UseRhinoStyle();Content=new StackLayout{Spacing=4,Items={_caption,_primary,_more}};}
    Button Make(ContextAction a,bool favorite,long usage){var text=$"{a.Icon} {(favorite?"★ ":"")}{a.Label}";var b=new Button{Text=text,ToolTip=$"{a.Hint}\nVerwendet: {usage}×",Height=30};b.Click+=(_,_)=>_execute(a);return b;}
    public void UpdateActions(SelectionContext c,IReadOnlyList<ContextAction> actions,ContextAssistSettings s){_caption.Text=c.Caption;_primary.Items.Clear();_more.Items.Clear();_more.Visible=false;var n=Math.Min(s.PrimaryCount,actions.Count);foreach(var a in actions.Take(n))_primary.Items.Add(Make(a,s.IsFavorite(c.Kind,a.Id),s.UsageCount(a.Id)));var rest=actions.Skip(n).ToList();if(rest.Count>0){var mb=new Button{Text=$"⋯ Mehr ({rest.Count})",Height=30};mb.Click+=(_,_)=>{_more.Visible=!_more.Visible;};_primary.Items.Add(mb);foreach(var a in rest)_more.Items.Add(Make(a,s.IsFavorite(c.Kind,a.Id),s.UsageCount(a.Id)));}var close=new Button{Text="×",ToolTip="Ausblenden",Width=30,Height=30};close.Click+=(_,_)=>_dismiss();_primary.Items.Add(close);}
    public void ShowAt(SelectionContext c,PopupPositionMode mode){PointF p=Mouse.Position;if(mode==PopupPositionMode.Geometry&&c.Anchor.IsValid){var v=RhinoDoc.ActiveDoc?.Views.ActiveView;if(v!=null){var q=v.ActiveViewport.WorldToClient(c.Anchor);var sr=v.ScreenRectangle;p=new PointF((float)(sr.Left+q.X),(float)(sr.Top+q.Y));}}Location=new Point((int)p.X+14,(int)p.Y+18);Show();var w=Screen.FromPoint(p).WorkingArea;var l=(int)w.Left;var t=(int)w.Top;var r=(int)w.Right;var b=(int)w.Bottom;Location=new Point(Math.Clamp(Location.X,l,Math.Max(l,r-Width)),Math.Clamp(Location.Y,t,Math.Max(t,b-Height)));}
}
